import type { Conversation } from "./supabase";
import { campaignOf, parseReferral } from "./campaigns";

const BIGIN_CONTACTS_URL = "https://www.zohoapis.com/bigin/v1/Contacts";
const ZOHO_TOKEN_URL = "https://accounts.zoho.com/oauth/v2/token";

// Zoho allows only a few token refreshes per 10 minutes — reuse the access token (valid 1 hour) instead of
// refreshing on every Bigin call (kept in memory per server instance; never stored anywhere readable).
let tokenCache: { token: string; exp: number } | null = null;
let tokenInflight: Promise<string> | null = null;

export async function getAccessToken(): Promise<string> {
  if (tokenCache && tokenCache.exp > Date.now()) return tokenCache.token;
  if (tokenInflight) return tokenInflight;
  tokenInflight = (async () => {
    let lastErr: unknown;
    for (let i = 0; i < 2; i++) {
      try {
        const token = await refreshAccessToken();
        tokenCache = { token, exp: Date.now() + 50 * 60e3 };
        return token;
      } catch (e) { lastErr = e; await new Promise(r => setTimeout(r, 3000)); }
    }
    throw lastErr;
  })().finally(() => { tokenInflight = null; });
  return tokenInflight;
}

async function refreshAccessToken(): Promise<string> {
  const refreshToken = process.env.BIGIN_REFRESH_TOKEN;
  const clientId = process.env.BIGIN_CLIENT_ID;
  const clientSecret = process.env.BIGIN_CLIENT_SECRET;

  if (!refreshToken || !clientId || !clientSecret) {
    throw new Error("Missing BIGIN_REFRESH_TOKEN, BIGIN_CLIENT_ID, or BIGIN_CLIENT_SECRET env vars");
  }

  const params = new URLSearchParams({
    grant_type: "refresh_token",
    refresh_token: refreshToken,
    client_id: clientId,
    client_secret: clientSecret,
  });

  const res = await fetch(`${ZOHO_TOKEN_URL}?${params.toString()}`, {
    method: "POST",
  });

  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Zoho token refresh failed: ${res.status} ${errText}`);
  }

  const data = await res.json();

  if (!data.access_token) {
    throw new Error(`Zoho token refresh returned no access_token: ${JSON.stringify(data)}`);
  }

  return data.access_token as string;
}


// ── Field metadata (cached per lambda) — map our values onto Bigin's real fields/types ──
type FieldMeta = { api_name: string; field_label: string; data_type: string; pick_list_values?: { display_value: string; actual_value: string }[] };
let fieldCache: FieldMeta[] | null = null;

async function getContactFields(accessToken: string): Promise<FieldMeta[] | null> {
  if (fieldCache) return fieldCache;
  try {
    const r = await fetch("https://www.zohoapis.com/bigin/v1/settings/fields?module=Contacts", {
      headers: { Authorization: `Zoho-oauthtoken ${accessToken}` },
    });
    if (!r.ok) { console.warn("[Bigin] field metadata unavailable:", r.status, await r.text().catch(() => "")); return null; }
    const j = await r.json();
    fieldCache = (j?.fields ?? []) as FieldMeta[];
    return fieldCache;
  } catch (e) { console.warn("[Bigin] field metadata error:", e); return null; }
}

const norm = (x: string) => x.toLowerCase().replace(/[^a-z0-9]/g, "");

// "Saturday", "tomorrow", "10 October", "2026-10-10" → "YYYY-MM-DD" (Dubai time)
// Marc: always show numbers as +971… (also in Bigin)
export function plusPhone(p: string | null | undefined): string {
  const d = String(p ?? "").replace(/\D/g, "");
  return d ? `+${d}` : "";
}

export function toIsoDate(raw: string): string | null {
  const v = raw.trim().toLowerCase();
  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  const now = new Date(Date.now() + 4 * 3600 * 1000);
  const iso = (d: Date) => d.toISOString().slice(0, 10);
  if (/\btoday\b/.test(v)) return iso(now);
  if (/\b(?:the\s+)?day\s+after\s+tomorrow\b|\bafter\s+tomorrow\b/.test(v))
    return iso(new Date(now.getTime() + 2 * 86400000));
  if (/\btomorrow\b/.test(v)) return iso(new Date(now.getTime() + 86400000));
  const days = ["sunday","monday","tuesday","wednesday","thursday","friday","saturday"];
  const months = ["jan","feb","mar","apr","may","jun","jul","aug","sep","oct","nov","dec"];
  const dm = v.match(/(\d{1,2})(?:st|nd|rd|th)?\s*(?:of\s*)?([a-z]{3})/) || null;
  const md = v.match(/([a-z]{3})[a-z]*\s*(\d{1,2})/) || null;
  const dmy = v.match(/(\d{1,2})[\/.-](\d{1,2})(?:[\/.-](\d{2,4}))?/);
  let day: number | null = null, mon: number | null = null;
  if (dm && months.includes(dm[2])) { day = +dm[1]; mon = months.indexOf(dm[2]); }
  else if (md && months.includes(md[1])) { day = +md[2]; mon = months.indexOf(md[1]); }
  else if (dmy) { day = +dmy[1]; mon = +dmy[2] - 1; }
  if (day != null && mon != null) {
    let y = now.getUTCFullYear();
    const cand = new Date(Date.UTC(y, mon, day));
    if (cand.getTime() < now.getTime() - 2 * 86400000) y++;
    return iso(new Date(Date.UTC(y, mon, day)));
  }
  const di = days.findIndex(d => v.includes(d));
  if (di >= 0) {
    let add = (di - now.getUTCDay() + 7) % 7;
    if (add === 0 && /\bnext\b/.test(v)) add = 7;
    return iso(new Date(now.getTime() + add * 86400000));
  }
  return null;
}

// Pick the picklist option that fits a value (exact text, or a numeric range like "25,000 - 50,000")
function matchPicklist(value: string, opts: { display_value: string; actual_value: string }[]): string | null {
  const exact = opts.find(o => norm(o.display_value) === norm(value) || norm(o.actual_value) === norm(value));
  if (exact) return exact.actual_value;
  const n = parseFloat(value.replace(/[^\d.]/g, ""));
  if (isNaN(n)) return null;
  for (const o of opts) {
    const t = o.display_value.toLowerCase().replace(/,/g, "");
    const nums = (t.match(/\d+(?:\.\d+)?\s*k?/g) ?? []).map(x => /k$/.test(x.trim()) ? parseFloat(x) * 1000 : parseFloat(x));
    if (nums.length >= 2 && n >= nums[0] && n <= nums[1]) return o.actual_value;
    if (nums.length === 1 && /(\+|above|over|more)/.test(t) && n >= nums[0]) return o.actual_value;
    if (nums.length === 1 && /(below|under|less|up to)/.test(t) && n <= nums[0]) return o.actual_value;
  }
  return null;
}

// "2pm", "2:30 pm", "14:00", "noon" → "14:00"
export function toTime24(raw: string): string | null {
  const v = raw.trim().toLowerCase();
  if (/\bnoon\b|\bmidday\b/.test(v)) return "12:00";
  const m = v.match(/(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm|a\.m\.|p\.m\.)?/);
  if (!m) return null;
  let h = +m[1]; const min = m[2] ?? "00"; const ap = m[3]?.replace(/\./g, "");
  if (ap === "pm" && h < 12) h += 12;
  if (ap === "am" && h === 12) h = 0;
  if (!ap && h >= 1 && h <= 7) h += 12; // "come at 5" during business hours = 17:00
  if (h > 23 || +min > 59) return null;
  return `${String(h).padStart(2, "0")}:${min}`;
}
const to12h = (t: string) => { const [h, m] = t.split(":").map(Number); return `${((h + 11) % 12) + 1}:${String(m).padStart(2, "0")} ${h >= 12 ? "PM" : "AM"}`; };
const prettyDate = (iso: string) => new Date(iso + "T12:00:00Z").toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric", timeZone: "UTC" });

// Fit an appointment value to whatever type the Bigin field is
function coerceAppointment(kind: "date" | "time", f: FieldMeta | null, dateRaw?: string, timeRaw?: string): unknown {
  const iso = dateRaw ? toIsoDate(dateRaw) : null;
  const t24 = timeRaw ? toTime24(timeRaw) : null;
  const type = f?.data_type ?? (kind === "date" ? "date" : "text");
  if (type === "datetime") return iso ? `${iso}T${t24 ?? "10:00"}:00+04:00` : null;
  if (type === "date") return iso;
  if (type === "picklist") {
    const opts = f?.pick_list_values ?? [];
    if (kind === "time" && t24) {
      const hit = opts.find(o => toTime24(o.display_value) === t24);
      return hit?.actual_value ?? null;
    }
    return matchPicklist(kind === "date" ? (dateRaw ?? "") : (timeRaw ?? ""), opts);
  }
  // text-like
  if (kind === "date") return iso ? prettyDate(iso) : dateRaw ?? null;
  return t24 ? to12h(t24) : timeRaw ?? null;
}

// Resolve our keys to Bigin api names (by api name, then by label) and coerce by type.
function adaptRecord(record: Record<string, string>, fields: FieldMeta[] | null): Record<string, unknown> {
  if (!fields) {
    const out: Record<string, unknown> = { ...record };
    const dr = record["Appointment_Date"], tr = record["Appointment_Time"];
    if (dr) { const d = coerceAppointment("date", null, dr, tr); if (d) out["Appointment_Date"] = d; else delete out["Appointment_Date"]; }
    if (tr) { const t = coerceAppointment("time", null, dr, tr); if (t) out["Appointment_Time"] = t; else delete out["Appointment_Time"]; }
    return out;
  }
  const byApi = new Map(fields.map(f => [f.api_name, f]));
  const byLabel = new Map(fields.map(f => [norm(f.field_label), f]));
  const out: Record<string, unknown> = {};
  for (const [key, raw] of Object.entries(record)) {
    if (raw == null || raw === "") continue;
    const f = byApi.get(key) ?? byLabel.get(norm(key.replace(/_/g, " ")));
    if (!f) { console.warn(`[Bigin] no field for "${key}" — skipped`); continue; }
    let v: unknown = raw;
    if (key === "Appointment_Date" || key === "Appointment_Time") {
      v = coerceAppointment(key === "Appointment_Date" ? "date" : "time", f, record["Appointment_Date"], record["Appointment_Time"]);
      if (v == null) { console.warn(`[Bigin] appointment "${raw}" doesn't fit ${f.api_name} (${f.data_type}) — skipped`); continue; }
      out[f.api_name] = v;
      continue;
    }
    switch (f.data_type) {
      case "picklist": v = matchPicklist(String(raw), f.pick_list_values ?? []); break;
      case "integer": case "bigint": { const n = parseInt(String(raw).replace(/[^\d]/g, ""), 10); v = isNaN(n) ? null : n; break; }
      case "double": case "currency": case "decimal": { const n = parseFloat(String(raw).replace(/[^\d.]/g, "")); v = isNaN(n) ? null : n; break; }
      case "date": v = toIsoDate(String(raw)); break;
      case "boolean": v = /^(yes|true|1)$/i.test(String(raw)); break;
    }
    if (v == null) { console.warn(`[Bigin] "${raw}" doesn't fit ${f.api_name} (${f.data_type}) — skipped`); continue; }
    out[f.api_name] = v;
  }
  return out;
}

// ── Red tags for records that need attention (existing customer) ──
const TAG_RED = "#F17574";
const ensuredTags = new Set<string>();
async function ensureRedTag(name: string, headers: Record<string, string>) {
  if (ensuredTags.has(name)) return;
  try {
    const r = await fetch("https://www.zohoapis.com/bigin/v1/settings/tags?module=Contacts", {
      method: "POST", headers, body: JSON.stringify({ tags: [{ name, color_code: TAG_RED }] }),
    });
    const t = await r.text();
    if (!r.ok && !/DUPLICATE|already/i.test(t)) console.warn(`[Bigin] create tag ${name}:`, r.status, t);
  } catch (e) { console.warn("[Bigin] create tag error:", e); }
  ensuredTags.add(name);
}
async function tagRecord(id: string, name: string, headers: Record<string, string>) {
  await ensureRedTag(name, headers);
  try {
    const r = await fetch(`https://www.zohoapis.com/bigin/v1/Contacts/${id}/actions/add_tags?tag_names=${encodeURIComponent(name)}&over_write=false`, { method: "POST", headers });
    const t = await r.text();
    console.log(`[Bigin] tag ${name} on ${id}:`, r.status, t.slice(0, 300));
  } catch (e) { console.warn("[Bigin] add tag error:", e); }
}

// Valid Bigin Sales_Inquiry picklist values
const VALID_SALES_INQUIRY = new Set([
  "Cash Deal",
  "Consignment",
  "Not Sure - Need Advise",
  "No Communication yet",
  "Price Offer Inquiry",
  "Home Visit Inquiry",
  "Trade-in Inquiry",
  "Other",
]);

// Maps internal sell_timeline values to Bigin picklist labels
function resolveSalesInquiry(conversation: Conversation & { sales_inquiry?: string }): string {
  const explicit = (conversation as any).sales_inquiry;
  if (explicit && VALID_SALES_INQUIRY.has(explicit)) return explicit;
  const st = (conversation as any).sell_timeline ?? "";
  if (st.includes("cash"))        return "Cash Deal";
  if (st.includes("consignment")) return "Consignment";
  if (st.includes("not_sure"))    return "Not Sure - Need Advise";
  if (st.includes("home_visit"))  return "Home Visit Inquiry";
  if (st.includes("trade_in"))    return "Trade-in Inquiry";
  if (st.includes("price_offer")) return "Price Offer Inquiry";
  // Explicit but unrecognised value → "Other"
  if (explicit) return "Other";
  return "No Communication yet";
}

export async function createBiginContact(
  conversation: Conversation & {
    sales_inquiry?: string;
    alternative_phone?: string;
    inquiry_summary?: string;
    inspection_booked?: boolean;
    owner_status?: string;
    car_conditions?: string;
  },
  attempt = 1
): Promise<boolean> {
  {
    const sim = (globalThis as any).__kayaSim as Map<string, string[]> | undefined;
    const log = sim?.get(String((conversation as any).phone ?? (conversation as any).phone_number ?? ""));
    if (log) {
      const c: any = conversation;
      log.push(`[BIGIN] name=${c.name ?? ""} car=${[c.make, c.model, c.year].filter(Boolean).join(" ")} km=${c.mileage ?? ""} specs=${c.specs ?? ""} booked=${!!c.inspection_booked} appt=${c.appointment_date ?? ""} ${c.appointment_time ?? ""} inquiry=${c.sales_inquiry ?? ""} tag=${c.milestone_tag ?? ""} est=${c.estimated_price ?? ""}`);
      return true;
    }
  }
  try {
    const accessToken = await getAccessToken();

    // Name: use customer name, fall back to car details, never leave empty
    const carFallback = [conversation.make, conversation.model, conversation.year]
      .filter(Boolean).join(" ");
    // Name never saved but given in the chat (answer to the name question) → use it, not the car
    let chatName: string | null = null;
    if (!conversation.name && Array.isArray((conversation as any).messages)) {
      const msgs = (conversation as any).messages as { role: string; content: string }[];
      for (let i = 0; i < msgs.length - 1 && !chatName; i++) {
        if (msgs[i].role === "assistant" && msgs[i + 1].role === "user" && /\b(your name|may i (know|have) your name)\b/i.test(msgs[i].content)) {
          const m = msgs[i + 1].content.trim().replace(/^(hi|hello|hey)[,!\s]+/i, "").match(/^(?:(?:my name is|i am|i'm|this is|it's)\s+)?([A-Za-z][A-Za-z'-]{1,20})(?:\s+([A-Za-z][A-Za-z'-]{1,20}))?[.!\s]*$/i);
          if (m) chatName = [m[1], m[2]].filter(Boolean).map(w => w[0].toUpperCase() + w.slice(1).toLowerCase()).join(" ");
        }
      }
    }
    const displayName = conversation.name || chatName || carFallback || "Unknown";
    // Full name goes into Last_Name only — First_Name is never used
    const lastName = displayName.trim();

    // Phone: always use conversation phone (WhatsApp sender) as primary
    const conversationPhone = (conversation as any).phone_number || (conversation as any).phone || "";
    // Alternative phone: only if explicitly different from conversation phone
    const altPhone = (conversation as any).alternative_phone ?? "";
    const primaryPhone = altPhone && altPhone !== conversationPhone ? altPhone : conversationPhone;

    const record: Record<string, string> = {
      Last_Name: lastName,
      Phone: plusPhone(primaryPhone || conversationPhone),
      Conversation_Phone_Number: plusPhone(conversationPhone),
      Lead_Source: "WhatsApp Bot",
      Source_Url: "WhatsApp Bot",
      Sales_Inquiry: resolveSalesInquiry(conversation as any),
    };

    // Lead source: which Meta ad / campaign the chat came from
    {
      const ref = parseReferral((conversation as any).source_url);
      if (ref) {
        record["Utm_Medium"] = "Meta ad (WhatsApp)";
        record["Utm_Campaign"] = campaignOf(ref).slice(0, 250);
        record["Utm_Content"] = [ref.source_id ? `Ad ${ref.source_id}` : "", ref.headline ?? ""].filter(Boolean).join(" | ").slice(0, 250);
        if (ref.source_url) record["Source_Url"] = ref.source_url.slice(0, 250);
      }
    }

    // Inspection_Booked: Yes if appointment confirmed, No otherwise
    record["Inspection_Booked"] = conversation.inspection_booked ? "Yes" : "No";

    if (conversation.make)             record["Make"]             = conversation.make;
    if (conversation.model)            record["Model"]            = conversation.model;
    if (conversation.year)             record["Year"]             = conversation.year;
    if (conversation.mileage)          { record["Mileage"] = conversation.mileage; record["Mileage_Range"] = conversation.mileage; }
    if (conversation.specs)            record["Regional_Specs"]   = conversation.specs;
    if (conversation.appointment_date) record["Appointment_Date"] = conversation.appointment_date;
    if (conversation.appointment_time) record["Appointment_Time"] = conversation.appointment_time;
    if (conversation.estimated_price)  record["Estimated_Price"]  = conversation.estimated_price;
    if (conversation.owner_status)     record["Owner_Status"]     = conversation.owner_status;
    if (conversation.car_conditions)   record["Car_Conditions"]   = conversation.car_conditions;
    {
      const isoD = conversation.appointment_date ? toIsoDate(conversation.appointment_date) : null;
      const t = conversation.appointment_time ? toTime24(conversation.appointment_time) : null;
      if (isoD && t) record["Appointment_Date_and_Time"] = `${isoD}T${t}:00+04:00`;
    }
    {
      const iso = conversation.appointment_date ? toIsoDate(conversation.appointment_date) : null;
      const t24 = conversation.appointment_time ? toTime24(conversation.appointment_time) : null;
      const apptLine = (conversation.appointment_date || conversation.appointment_time)
        ? `Appointment: ${iso ? prettyDate(iso) : conversation.appointment_date ?? "?"}${t24 ? ", " + to12h(t24) : conversation.appointment_time ? ", " + conversation.appointment_time : ""}`
        : "";
      const summary = [apptLine, conversation.inquiry_summary].filter(Boolean).join("\n\n");
      if (summary) record["Inquiry_Summary"] = summary;
    }

    const headers = {
      Authorization: `Zoho-oauthtoken ${accessToken}`,
      "Content-Type": "application/json",
    };

    // Upsert: find existing contact by the WhatsApp number, update it; otherwise create.
    // Lets us push at every milestone (follow-up, booking, timeout) without duplicates.
    // Milestones (booking, reschedule, cancel, follow-up) → always a NEW record so it shows up in
    // the pipeline. If the customer already exists, the new record gets a red tag + a note on top.
    // Other pushes (12-min silence, details completed) update the newest record for this number.
    const milestone = (conversation as any).milestone_tag as string | undefined;
    let existingId: string | null = null;
    let applyTag: string | null = null;
    let rows: any[] = [];
    if (conversationPhone) {
      // Older contacts were saved without "+", new ones with it — search both
      let sr = await fetch(`${BIGIN_CONTACTS_URL}/search?phone=${encodeURIComponent(plusPhone(conversationPhone))}`, { headers });
      if (sr.status === 204) sr = await fetch(`${BIGIN_CONTACTS_URL}/search?phone=${encodeURIComponent(String(conversationPhone).replace(/\D/g, ""))}`, { headers });
      if (sr.status === 200) {
        const sj = await sr.json().catch(() => null);
        rows = Array.isArray(sj?.data) ? sj.data : [];
        rows.sort((a, b) => String(b.Created_Time ?? "").localeCompare(String(a.Created_Time ?? "")));
      } else if (sr.status !== 204) {
        console.warn("[Bigin] search failed:", sr.status, await sr.text().catch(() => ""));
      }
    }
    if (milestone) {
      if (rows.length > 0) {
        applyTag = milestone;

        record["Inquiry_Summary"] = `[${milestone}] Existing customer — needs attention.\n\n${record["Inquiry_Summary"] ?? ""}`.trim();
      }
    } else {
      existingId = rows[0]?.id ?? null;
    }

    const fields = await getContactFields(accessToken);
    const data = adaptRecord(record, fields);
    if ((conversation as any).clear_appointment) {
      for (const label of ["Appointment Date", "Appointment Time", "Appointment Date and Time"]) {
        const f = fields?.find(x => norm(x.field_label) === norm(label));
        data[f?.api_name ?? label.replace(/ /g, "_")] = null;
      }
    }
    data["First_Name"] = null; // never used — clears leftovers like "Unknown" on existing contacts

    // If Bigin rejects a field (INVALID_DATA etc.), drop just that field and retry —
    // one bad value must never cost us the whole record.
    let text = "";
    let savedId: string | null = null;
    for (let tries = 0; tries < 6; tries++) {
      const body = JSON.stringify({ data: [existingId ? { id: existingId, ...data } : data] });
      console.log(`[Bigin] ${existingId ? "updating " + existingId : "creating"}:`, body);
      const res = await fetch(BIGIN_CONTACTS_URL, { method: existingId ? "PUT" : "POST", headers, body });
      text = await res.text();
      const result = (() => { try { return JSON.parse(text); } catch { return null; } })();
      const row = result?.data?.[0];
      if (res.ok && (!row?.status || row.status === "success")) { savedId = row?.details?.id ?? existingId; break; }
      const bad = row?.details?.api_name as string | undefined;
      if (bad && bad in data) {
        console.warn(`[Bigin] field ${bad} rejected (${row?.code}: ${row?.message}) — retrying without it`);
        delete data[bad];
        continue;
      }
      throw new Error(`Bigin ${existingId ? "update" : "create"} failed: ${res.status} ${text}`);
    }
    console.log(`[Bigin] contact ${existingId ? "updated" : "created"}:`, text);
    if (applyTag && savedId) await tagRecord(savedId, applyTag, headers);
    // Far-away timing ("after Eid", "next month"): Next Follow up Date on the pipeline card → the
    // night workflow moves it to Call Later, so the call center gets it back at the right time
    {
      const fu = String((conversation as any).car_conditions ?? "").match(/Follow-up: (\d{4}-\d{2}-\d{2})/)?.[1];
      if (fu && savedId) await setFollowUpDate(savedId, fu, headers).catch(e => console.warn("[Bigin] follow-up date not set:", e));
    }
    return true;
  } catch (error) {
    if (attempt < 3) {
      console.warn(`[Bigin] attempt ${attempt} failed, retrying in 3s...`);
      await new Promise(r => setTimeout(r, 3000));
      return createBiginContact(conversation, attempt + 1);
    }
    console.error("Bigin contact creation error (all retries failed):", error);
    return false;
  }
}

// ── Booked customer requests → a task on the existing Bigin contact ──
// Linked to the customer's latest WhatsApp pipeline card, with a link, car details, name and all phone numbers.
export async function createChangeTask(
  conversation: Record<string, any>,
  kind: "RESCHEDULE" | "CANCEL" | "OTHER",
  request: string,
): Promise<{ ok: boolean; taskId?: string; dealId?: string; error?: string }> {
  try {
    const sim = (globalThis as any).__kayaSim as Map<string, string[]> | undefined;
    const simLog = sim?.get(String(conversation.phone ?? ""));
    const token = await getAccessToken();
    const headers = { Authorization: `Zoho-oauthtoken ${token}`, "Content-Type": "application/json" };
    const phone = String(conversation.phone_number || conversation.phone || "");
    const ORG = "https://bigin.zoho.com/bigin/org869557047/Home#";

    // Contact(s) for this WhatsApp number (old ones saved without "+")
    let contacts: any[] = [];
    for (const q of [plusPhone(phone), phone.replace(/\D/g, "")]) {
      const r = await fetch(`${BIGIN_CONTACTS_URL}/search?phone=${encodeURIComponent(q)}`, { headers });
      if (r.status === 200) { contacts = ((await r.json().catch(() => null))?.data ?? []); if (contacts.length) break; }
    }
    contacts.sort((a, b) => String(b.Created_Time ?? "").localeCompare(String(a.Created_Time ?? "")));
    if (!contacts.length && !simLog) {
      console.error("[Bigin] cannot link booking task: existing contact not found for", phone);
      return { ok: false, error: "Existing Bigin contact not found" };
    }

    // Their latest pipeline card
    let deal: any = null;
    for (const c of contacts.slice(0, 5)) {
      const r = await fetch(`https://www.zohoapis.com/bigin/v1/Contacts/${c.id}/Pipelines?fields=Deal_Name,Stage,Created_Time`, { headers });
      if (r.status === 200) {
        const rows = ((await r.json().catch(() => null))?.data ?? []) as any[];
        rows.sort((a, b) => String(b.Created_Time ?? "").localeCompare(String(a.Created_Time ?? "")));
        if (rows[0]) { deal = rows[0]; break; }
      }
    }

    const name = conversation.name || contacts[0]?.Last_Name || "Unknown";
    const car = [conversation.make, conversation.model, conversation.year].filter(Boolean).join(" ") || "car unknown";
    const km = conversation.mileage ? `${String(conversation.mileage).replace(/\B(?=(\d{3})+(?!\d))/g, ",")} km` : "";
    const phones = [plusPhone(phone), conversation.alternative_phone ? plusPhone(conversation.alternative_phone) : ""].filter(Boolean);
    const appt = [conversation.appointment_date, conversation.appointment_time].filter(Boolean).join(" ");
    const dubai = new Date(Date.now() + 4 * 3600e3);
    const due = dubai.getUTCHours() >= 19 || dubai.getUTCDay() === 0
      ? new Date(dubai.getTime() + (dubai.getUTCDay() === 6 && dubai.getUTCHours() >= 19 ? 2 : 1) * 86400e3) : dubai;
    const subject = `${kind === "OTHER" ? "BOOKING INQUIRY" : kind}: ${name} | ${car}`;
    const history = (Array.isArray(conversation.messages) ? conversation.messages : [])
      .slice(-20).map((m: any) => `${m.role === "assistant" ? "Kaya" : "Customer"}: ${String(m.content ?? "").slice(0, 550)}`);
    const description = [
      kind === "RESCHEDULE" ? "Customer requested RESCHEDULE. Call to confirm a new slot and update the existing booking record; the original time is no longer confirmed with the customer."
        : kind === "CANCEL" ? "Customer CANCELLED the inspection. Call to reconfirm the decision or reverse the cancellation if the customer wants to keep the booking, and update the existing record."
        : "Customer has an inquiry about a confirmed appointment — team action required.",
      `Customer wrote: "${request.slice(0, 300)}"`,
      appt ? `Current appointment: ${appt}` : "",
      "",
      `Name: ${name}`,
      `Phone: ${phones.join(" / ")}`,
      `Car: ${car}${km ? ", " + km : ""}${conversation.specs ? ", " + conversation.specs : ""}`,
      conversation.car_conditions ? `Car and conversation notes: ${String(conversation.car_conditions).slice(0, 1200)}` : "",
      "Recent conversation:", ...history,
      "",
      deal ? `Pipeline record: ${ORG}/deals/${deal.id}` : "",
      contacts[0] ? `Contact: ${ORG}/contacts/${contacts[0].id}` : "",
    ].filter((l, i, a) => l !== "" || (a[i - 1] ?? "") !== "").join("\n");

    if (simLog) { simLog.push(`[TASK] ${subject}\n${description}`); return { ok: true, taskId: "sim", dealId: deal?.id }; }

    const task: Record<string, unknown> = { Subject: subject, Due_Date: due.toISOString().slice(0, 10), Priority: "High", Description: description };
    if (contacts[0]) task["Who_Id"] = { id: contacts[0].id };
    if (deal) { task["$related_module"] = "Deals"; task["Related_To"] = { id: deal.id }; }
    else if (contacts[0]) { task["$related_module"] = "Contacts"; task["Related_To"] = { id: contacts[0].id }; }
    const res = await fetch("https://www.zohoapis.com/bigin/v1/Tasks", { method: "POST", headers, body: JSON.stringify({ data: [task] }) });
    const text = await res.text();
    const row = (() => { try { return JSON.parse(text)?.data?.[0]; } catch { return null; } })();
    if (!res.ok || (row?.status && row.status !== "success")) {
      console.error("[Bigin] task create failed:", res.status, text.slice(0, 400));
      return { ok: false, error: `${res.status} ${text.slice(0, 200)}` };
    }
    console.log(`[Bigin] ${kind} task created for ${phone} (deal ${deal?.id ?? "-"})`);
    return { ok: true, taskId: row?.details?.id, dealId: deal?.id };
  } catch (e) {
    console.error("[Bigin] task create error:", e);
    return { ok: false, error: String(e) };
  }
}

// Move a newly handed-off lead into the Call Back card column after Bigin's
// contact-to-pipeline workflow creates its card. Never creates a task.
export async function moveLeadToCallBack(phone: string): Promise<boolean> {
  try {
    const sim = (globalThis as any).__kayaSim as Map<string, string[]> | undefined;
    const simLog = sim?.get(phone);
    if (simLog) { simLog.push("[BIGIN] move lead to Call Back"); return true; }
    const token = await getAccessToken();
    const headers = { Authorization: `Zoho-oauthtoken ${token}`, "Content-Type": "application/json" };
    let contacts: any[] = [];
    for (const q of [plusPhone(phone), phone.replace(/\D/g, "")]) {
      const r = await fetch(`${BIGIN_CONTACTS_URL}/search?phone=${encodeURIComponent(q)}`, { headers, cache: "no-store" });
      if (r.status === 200) { contacts = (await r.json())?.data ?? []; if (contacts.length) break; }
    }
    contacts.sort((a, b) => String(b.Created_Time ?? "").localeCompare(String(a.Created_Time ?? "")));
    const contact = contacts[0];
    if (!contact) return false;
    for (let attempt = 0; attempt < 4; attempt++) {
      const r = await fetch(`https://www.zohoapis.com/bigin/v1/Contacts/${contact.id}/Pipelines?fields=Stage,Created_Time`, { headers, cache: "no-store" });
      const deals = r.status === 200 ? ((await r.json())?.data ?? []) as any[] : [];
      deals.sort((a, b) => String(b.Created_Time ?? "").localeCompare(String(a.Created_Time ?? "")));
      if (deals[0]?.id) {
        if (String(deals[0].Stage ?? "").toLowerCase() === "call back") return true;
        const u = await fetch("https://www.zohoapis.com/bigin/v1/Pipelines", {
          method: "PUT", headers, body: JSON.stringify({ data: [{ id: deals[0].id, Stage: "Call Back" }] }),
        });
        const body = await u.json().catch(() => null);
        const ok = u.ok && body?.data?.[0]?.status === "success";
        if (!ok) console.error("[Bigin] Call Back stage update failed:", u.status, JSON.stringify(body).slice(0, 400));
        return ok;
      }
      await new Promise(resolve => setTimeout(resolve, 1500));
    }
    console.warn("[Bigin] Call Back card not created yet for", phone);
    return false;
  } catch (e) {
    console.error("[Bigin] Call Back move error:", e);
    return false;
  }
}


// The pipeline card is created from the contact by a Bigin workflow, so it can lag a few seconds
async function setFollowUpDate(contactId: string, date: string, headers: Record<string, string>) {
  for (let i = 0; i < 3; i++) {
    const r = await fetch(`https://www.zohoapis.com/bigin/v1/Contacts/${contactId}/Pipelines?fields=Deal_Name,Stage,Created_Time`, { headers, cache: "no-store" });
    const deals = r.status === 200 ? ((await r.json())?.data ?? []) : [];
    const latest = deals.sort((a: any, b: any) => String(b.Created_Time).localeCompare(String(a.Created_Time)))[0];
    if (latest?.id) {
      const u = await fetch("https://www.zohoapis.com/bigin/v1/Pipelines", { method: "PUT", headers, body: JSON.stringify({ data: [{ id: latest.id, Next_Follow_up_Date: date }] }) });
      console.log(`[Bigin] follow-up date ${date} on deal ${latest.id}: ${u.status}`);
      return;
    }
    await new Promise(res => setTimeout(res, 4000));
  }
}

